local db=WoWForeverIT_QuestIT.DataIT
db[92515] = db[92515] or {}
db[92515]["reward"] = db[92515]["reward"] or {it="Non ti avevo promesso che sarebbe stato un lavoro pulito, vero?",enHash={"526d6445"}}
db[92516] = db[92516] or {}
db[92516]["reward"] = db[92516]["reward"] or {it="Ottimo lavoro, e anche in fretta. Niente male davvero.",enHash={"42d833d7"}}
db[92517] = db[92517] or {}
db[92517]["reward"] = db[92517]["reward"] or {it="Con i banditi dispersi abbiamo un problema in meno. Temo però che i superstiti possano cercare protezione nel culto, ingrossandone le file già sempre più preoccupanti.\n\nComunque, accettiamo le vittorie quando arrivano.",enHash={"c4359f82","a4ea20a6","6247b850"}}
db[92553] = db[92553] or {}
db[92553]["reward"] = db[92553]["reward"] or {it="Queste uova non sono facili da procurare, ma che i venti mi assistano: fritte in un po’ di sego di ursera sono DELIZIOSE!\n\nSe hai tempo e ti piace cucinare, posso insegnarti qualche trucco imparato negli anni. Basta chiedere e sarò felice di addestrarti.",enHash={"c5d93846","56de9a84","b790ba2e"}}
db[92597] = db[92597] or {}
db[92597]["reward"] = db[92597]["reward"] or {it="Lo senti? Sì? Bene! Hai mosso i primi passi. Con le tue capacità potrai attingere all’energia magica latente in molti luoghi, ottenendo benefici diversi: alcuni profondi, altri più sottili. Non saprai quali finché non proverai, ma è proprio questa la parte migliore del dono: rendere noto ciò che è ignoto.\n\nPer sopravvivere a questi tempi difficili dobbiamo cercare conoscenza... e potere, senza esitare.",enHash={"49236d34","544feb20","1f1d7ab6"}}
db[93318] = db[93318] or {}
db[93318]["progress"] = db[93318]["progress"] or {it="Mi servirà la testa della creatura come prova della tua impresa.",enHash={"895b533e"}}
db[93318] = db[93318] or {}
db[93318]["reward"] = db[93318]["reward"] or {it="Come se il culto e i banditi delle alture non bastassero, non ci serviva anche un vuldren gigante a terrorizzare i cittadini. Oggi hai fatto qualcosa di grande. Come promesso, ecco la tua ricompensa.",enHash={"75994968"}}
db[93319] = db[93319] or {}
db[93319]["reward"] = db[93319]["reward"] or {it="Grazie, $C. Per ora ci aiuterà a tirare avanti. Ma se non riusciamo presto a ripristinare le vie di rifornimento, qualche pietra del vento rubata sarà l’ultimo dei nostri problemi.",enHash={"d366abec"}}
db[93951] = db[93951] or {}
db[93951]["reward"] = db[93951]["reward"] or {it="Raccogliere piume per adornare i capelli può sembrare una frivolezza. Eppure, anche in tempi come questi, dobbiamo cercare di apprezzare le piccole gioie.\n\nSe una mia creazione rende felice qualcuno, per me è una buona giornata. Grazie per queste piume e per avermi aiutata a portare un po’ di gioia a Zephras.",enHash={"bae825f0","bd11854e","b9ba6278"}}
db[94411] = db[94411] or {}
db[94411]["reward"] = db[94411]["reward"] or {it="Scontrarci direttamente con i nostri fratelli e sorelle shen’dorei ci indebolisce come popolo, ma talvolta occorre agire con decisione per evitare tragedie peggiori.\n\nI maghi dell’Alto Ordine non si curano delle conseguenze delle loro interferenze magiche. Le forze che tengono unita l’isola sono fragili e vulnerabili: basterebbe una sola azione avventata per distruggere la nostra casa.",enHash={"d84c929a","58550350","55479666"}}

