db[99049]=db[99049] or {}
db[99049]["text"]=db[99049]["text"] or {it="L’area circostante è devastata e mostra evidenti segni di uno scontro. Chiunque abbia teso l’imboscata a Heglan non ne è uscito illeso. Probabilmente qui vicino ci sono tracce di quanto è accaduto.\nOrgnil vorrà sicuramente vedere qualsiasi prova lasciata dagli assalitori.",enHash={"2cd1ab95"}}
db[99049]=db[99049] or {}
db[99049]["objectives"]=db[99049]["objectives"] or {it="Trova tracce di ciò che ha attaccato Heglan Shadeeye.",enHash={"b62fc3ae"}}

